import { buildOnly } from "../../src/vite/build-only";

type PluginRecord = Record<string, any>;

describe("buildOnly", () => {
  test("preserves plugin name", () => {
    const plugin = buildOnly({ name: "test-plugin" }) as PluginRecord;
    expect(plugin.name).toBe("test-plugin");
  });

  test("passes through hooks in build mode", () => {
    const transform = jest.fn().mockReturnValue("transformed");
    const original = { name: "test-plugin", transform } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "build" });

    const result = plugin.transform("code", "id");
    expect(transform).toHaveBeenCalledWith("code", "id");
    expect(result).toBe("transformed");
  });

  test("suppresses hooks in serve mode", () => {
    const transform = jest.fn();
    const original = { name: "test-plugin", transform } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "serve" });

    const result = plugin.transform("code", "id");
    expect(transform).not.toHaveBeenCalled();
    expect(result).toBeUndefined();
  });

  test("preserves non-function properties", () => {
    const original = {
      name: "test-plugin",
      enforce: "post",
    } as any;
    const plugin = buildOnly(original) as PluginRecord;
    expect(plugin.enforce).toBe("post");
  });

  test("wraps multiple hooks", () => {
    const options = jest.fn();
    const generateBundle = jest.fn();
    const original = {
      name: "test-plugin",
      options,
      generateBundle,
    } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "serve" });

    plugin.options({});
    plugin.generateBundle({}, {});
    expect(options).not.toHaveBeenCalled();
    expect(generateBundle).not.toHaveBeenCalled();
  });

  test("calls inner configResolved in build mode", () => {
    const configResolved = jest.fn();
    const original = { name: "test-plugin", configResolved } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "build" });

    expect(configResolved).toHaveBeenCalledWith({ command: "build" });
  });

  test("suppresses inner configResolved in serve mode", () => {
    const configResolved = jest.fn();
    const original = { name: "test-plugin", configResolved } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "serve" });

    expect(configResolved).not.toHaveBeenCalled();
  });

  test("preserves this context on hook calls", () => {
    let capturedThis: any;
    const original = {
      name: "test-plugin",
      buildStart(this: any) {
        capturedThis = this;
      },
    } as any;
    const plugin = buildOnly(original) as PluginRecord;
    plugin.configResolved({ command: "build" });

    const ctx = { meta: { rollupVersion: "4" } };
    plugin.buildStart.call(ctx);
    expect(capturedThis).toBe(ctx);
  });
});
